  f.push([S.Z2_D1, S.Z2_Y1, M.WALL5_D0, M.WALL5_TOP, BK.WALL5, 0.85, 1]);
  f.push([M.WALL5_D0, M.WALL5_TOP, M.WALL5_D1, M.WALL5_TOP, BK.STONE, 1, 0.7]);
