const BOWL_VS = /* glsl */`
attribute vec4 aSec; attribute vec3 aRow;
varying vec3 vW; varying vec3 vN; varying vec4 vSec; varying vec3 vRow;
void main() { vec4 w = modelMatrix * vec4(position, 1.); vW = w.xyz; vN = normal; vSec = aSec; vRow = aRow; gl_Position = projectionMatrix * viewMatrix * w; }`;
PIECES.push(async function bowl(H) {
  const g = faces(), sec = [], row = [], F = bowlSection(H.opts.seats !== false), NT = BOWLC.NT;
  const P = (d, y, k) => { const t = Math.PI * 2 * k / NT; return [ringA(d) * Math.cos(t), y, ringB(d) * Math.sin(t)]; };
  for (let k = 0; k < NT; k++) {
    for (const f of F) {
      quad(g, P(f[0], f[1], k), P(f[0], f[1], k + 1), P(f[2], f[3], k + 1), P(f[2], f[3], k), 1, 0);
      const r = f[7] || [0, 1, 1], u0 = k * M.BAYS / NT, u1 = (k + 1) * M.BAYS / NT;
      sec.push(f[0], u0, f[4], f[5], f[0], u1, f[4], f[5], f[2], u1, f[4], f[6], f[2], u0, f[4], f[6]);
      for (let q = 0; q < 4; q++) row.push(r[0], r[1], r[2]);
    }
    if (k % 48 === 47) await H.ctx.yield();
  }
  const geo = new THREE.BufferGeometry();
  geo.setAttribute('position', new THREE.Float32BufferAttribute(g.pos, 3)); geo.setAttribute('normal', new THREE.Float32BufferAttribute(g.nor, 3));
  geo.setAttribute('aSec', new THREE.Float32BufferAttribute(sec, 4)); geo.setAttribute('aRow', new THREE.Float32BufferAttribute(row, 3)); geo.setIndex(g.idx);
  const mat = new THREE.ShaderMaterial({ uniforms: { ...H.U }, vertexShader: BOWL_VS, fragmentShader: BOWL_FS, side: THREE.DoubleSide });
  H.bowlMat = mat;
  H.add('bowl', new THREE.Mesh(geo, mat), g.idx.length / 3).frustumCulled = false;
});

const BOWL_FS = /* glsl */`
varying vec3 vW; varying vec3 vN; varying vec4 vSec; varying vec3 vRow;
${LIGHT_GLSL}
${NOISE_GLSL}
void main() {
  float d = vSec.x, bayU = vSec.y, kind = floor(vSec.z + .5), ao = vSec.w;
  vec3 N = normalize(vN);
  float fa = FA_A + d, fb = FA_B + FA_K * d;
  vec2 rad = normalize(vec2(vW.x / (fa * fa), vW.z / (fb * fb)) + vec2(1e-6, 0.));
  vec3 E = normalize(vW - cameraPosition);
  float fwD = fwidth(d);
  // the gates' passages on the long axis are cut out of the stone (their own piece stands in the cut)
  vec2 gq = vec2(abs(vW.z), vW.y - ${BOWLC.GATE_SPRING.toFixed(2)});
  float inGate = step(gq.x, ${BOWLC.GATE_HALF.toFixed(2)}) * (gq.y < 0. ? 1. : step(dot(gq, gq), ${(BOWLC.GATE_HALF * BOWLC.GATE_HALF).toFixed(3)}));
  if (inGate > .5 && abs(vW.x) > 30. && d < ${BOWLC.GATE_LEN.toFixed(1)} && d > -1.4) discard;
  vec3 alb = ${v3(COLOUR.MARBLE)};
  float under = 0.;
  if (kind == ${BK.ROWS}. || kind == ${BK.WOOD_ROWS}.) {
    // a slope of rows: which face of a step the eye meets (the tread from above, the riser from across)
    float fd = (d - vRow.x) / vRow.y, f = fract(fd), rowI = floor(fd);
    float vd = dot(E.xz, rad), vy = -E.y;
    float riser = vd > 0. ? step((1. - f) * vRow.y * max(vy, 0.), f * vRow.z * vd) : 0.;
    float share = vd > 0. ? clamp(vRow.z * vd / max(vRow.z * vd + vRow.y * max(vy, 0.), 1e-4), 0., 1.) : 0.;
    float fine = 1. - smoothstep(.3, .75, fwD / vRow.y);
    riser = mix(share, riser, fine);
    float back = vd > 0. && vy > 0. ? clamp(f + f * vRow.z * vd / max(vy * vRow.y, 1e-4), 0., 1.) : f;
    float seam = (1. - riser) * (1. - .45 * smoothstep(.72, 1., back) * fine);
    N = normalize(mix(vec3(0., 1., 0.), vec3(-rad.x, 0., -rad.y), riser));
    ao *= mix(seam, .82, riser);
    if (kind == ${BK.WOOD_ROWS}.) { alb = ${v3(COLOUR.TIMBER)} * (1.25 + .2 * hash21(vec2(rowI, floor(bayU)))); }
    else {
      alb *= .97 + .05 * hash21(vec2(rowI, floor(bayU * 6.)));
      // the stairs' mouths: dark door openings 2.5 m wide in two rings (forty in each zone), drawn only
      float bw = 6.2831853 * .5 * (fa + fb) / ${M.BAYS.toFixed(1)};
      float first = step(vRow.x, 10.);
      float mouthBay = mod(floor(bayU) + first, 2.);
      float mx = abs(fract(bayU) - .5) * bw, my = fd - (first > .5 ? 9. : 3.);
      float mouth = mouthBay * step(mx, 1.1) * step(0., my) * step(my, 3.2);
      // a mouth is a stair's well: its near steps still catch the sky, its far end is deep
      alb = mix(alb, ${v3(COLOUR.TRAVERTINE)} * mix(.6, .26, smoothstep(.2, 2.6, my)), mouth); under = mouth * .65;
    }
  } else if (kind == ${BK.TIMBER}.) {
    alb = ${v3(COLOUR.TIMBER)} * (1.1 + .25 * vnoise(vec2(bayU * 9., d * 1.3)));
    alb *= 1. - .2 * (1. - smoothstep(0., .06, abs(fract(bayU) - .5) - .47));
  } else if (kind == ${BK.WALL5}.) {
    // the wall under the colonnade, with doors and windows in it
    alb = ${v3(COLOUR.TRAVERTINE)};
    float y = vW.y - ${SECTION.Z2_Y1.toFixed(2)};
    float bx = abs(fract(bayU) - .5) * 6.2831853 * .5 * (fa + fb) / ${M.BAYS.toFixed(1)};
    float door = step(bx, .6) * step(y, 2.3);
    float win = step(abs(bx - 1.9), .35) * step(abs(y - 3.4), .5);
    alb = mix(alb, ${v3(COLOUR.DARK)}, max(door, win)); under = max(door, win);
  } else if (kind == ${BK.LEDGE}. || kind == ${BK.PIT}.) {
    alb = ${v3(COLOUR.TRAVERTINE)} * .9;
    // wet where the water laps it: the pit's wall and the ledge's inner edge, the border wavering on the world's clock
    float lap = .32 + .1 * sin(bayU * 23. + uTime * 1.1) * sin(bayU * 9.7 - uTime * .8);
    float wet = kind == ${BK.PIT}. ? 1. : 1. - smoothstep(lap - .08, lap + .08, d + 1.5);
    alb *= mix(1., .5, wet);
  } else if (kind == ${BK.COLUMN}.) {
    // grey granite and cipollino (white marble with grey green waves) by turns
    float wave = sin(vW.y * 2.2 + 4. * vnoise(vec2(bayU * 5., vW.y * .9)));
    alb = vRow.x < .5 ? vec3(.36, .36, .38) * (.85 + .3 * hash21(floor(vW.xy * 9.))) : mix(vec3(.72, .74, .7), vec3(.42, .5, .44), smoothstep(.2, .9, wave));
  } else if (kind == ${BK.GATE}.) {
    // a gate's passage: dimmer the deeper it runs from either end
    float deep = min(abs(vW.x) - ${M.ARENA_A.toFixed(1)}, ${M.RIM_A.toFixed(1)} - abs(vW.x));
    alb = ${v3(COLOUR.TRAVERTINE)} * .8; ao *= .12 + .6 * exp(-max(deep, 0.) / 5.); under = 1.;
  } else {
    // marble: the podium wall and its platforms, the walkway and its low wall
    alb *= .97 + .05 * hash21(floor(vec2(bayU * 4., vW.y * 1.2)));
  }
  vec3 sun = sunAt(vW + N * .05) * uSunCol * max(dot(N, uSun), 0.) * (1. - under);
  // under the cloth the sky's fill is the cloth's own dyed glow (the one law's fillAt)
  float jf = fract(bayU / ${M.BAYS.toFixed(1)}) * ${M.MASTS.toFixed(1)};
  vec3 col = alb * (sun + fillAt(vW, N, d, jf) * ao);
  gl_FragColor = vec4(hazed(col, vW), 1.);
}`;

// THE COLONNADE on the 5 m wall (80 columns 7 m tall, grey granite and cipollino by turns, plain capitals: count, height
// and capitals INVENTED BY NEED), THE TWO GATES on the long axis (tall arched passages straight through the building,
