    tube(g, [x, y0 + 0.3, z], [x, y1 - 0.5, z], C.COL_R, C.COL_R * 0.86, 8, BK.COLUMN, undefined);
    tube(g, [x, y1 - 0.5, z], [x, y1 + 0.1, z], C.COL_R * 0.9, C.COL_R * 1.6, 8, BK.COLUMN, undefined);
