    q([x0, 0, r], [x0, 0, hb], [x0, top, hb], [x0, top, r], 1, BK.STONE);
    q([x0, 0, -hb], [x0, 0, -r], [x0, top, -r], [x0, top, -hb], 1, BK.STONE);
