// ------------------------------------------------------------------ THE VALLEY'S LAWS (the world file makes the meshes)
// Plain arithmetic, read by the world file and by the builder's count alike. SURE that the Baths and the old palace
// wing stood in 80; of the temple on its terrace the terrace research says: stood, or was building, in 80 (how much of
