        const fw = lerp(ring.front, rng()), r = [rng(), rng(), rng(), rng(), rng()], x0 = x, x1 = x + fw, z0 = z, z1 = z + bd, cx = (x0 + x1) / 2, cz = (z0 + z1) / 2, rr = Math.hypot(cx, cz);
