        if (x1 > T.XW - 6 && x0 < T.X1 + 6 && z1 > T.Z0 - 6 && z0 < T.Z1 + 6) continue;
        if ((cx * cx) / (pa * pa) + (cz * cz) / (pb * pb) < 1) continue;
        if (x1 > F.PRECINCT[0] && x0 < F.PRECINCT[1] && z1 > F.PRECINCT[2] && z0 < F.PRECINCT[3]) continue;
        if (inBox(hm.terrace, x0, x1, z0, z1, 10)) continue;
