// THE AIR'S LIFE (INVENTED, OURS): BIRDS in flocks, each flock wheeling on one level oval on the world's clock: six
// over the roofs east of the open ground, three round the wall's top outside it, one about the temple's roof on the
// terrace (the owner's word of 13:14: ONE flock there; a flock like the others in number and pace, on an oval K
// times the temple's half sides about its middle, clear of its corners by 3.9 m and more, at the eaves' and the
// roof's height). A flock's oval is kept, BY PLACE, clear of the route's line: over the roofs its whole reach lies
// 10 m and more to the side of the line's plan; round the wall its birds fly under y 49.1 where the line passes at
// 58 m and more; the temple's flock flies 8 m and more to the side of the line's plan and 8 m and more over it.
// EACH FLOCK IS DEALT FROM A STREAM OF ITS OWN (streamOf('birds-' + its number), 'birds-temple'): its tries for a
// place, then its own birds (five numbers a bird); so a change of the line or one flock more deals no other flock
// anew. EVERY FLOCK HAS ITS OWN PLACE ON ITS OVAL AT THE CLOCK'S NOUGHT (phase: a roof flock's is the last number
// of its stream, after its birds'; a wall flock's and the temple's are drawn with their measures). Returns for each
// flock: its centre, its oval's two radii, its turn's rate (radians a second, signed), its number, its spread, its
// phase and its birds' numbers.
