  STALL: { EVERY: 4.6, W: 3.3, D: 2.5, FRONT: 2.7, BACK: 2.05, TABLE: 0.85, KNOT: [2, 5], STAND: [0.7, 2.3], PHASE: 0.11 },
  PINE: { OUT: 12.5, EVERY: 10.5, H: [16.5, 19], R: [4.4, 5.6], PHASE: 0.71 },
