// 0.55 m standing, 0.50 m on the paths, 0.60 m walking) BUT BEFORE A STALL OF THE ROWS (356 pairs in 607 knots, on 39
// of the 40 seeds: the 16th try kept) AND BETWEEN TWO KNOTS OF BEARERS AT THE LITTERS SET DOWN (289 pairs, 7 a seed:
// those knots are dealt with no look at each other; 9 pairs more on the terrace). The market way's own standers
// (outsidePlan) are dealt one by one before a stall, in no knot's law: 26 such pairs a seed. Walkers of different
// knots cross one another's lines.
// NOTHING HERE READS THE LENS; the flown line is read as a place of the world. HOW THE CLEAR AIR IS KEPT (counted in
