// shots/flavian-amphitheatre/p1d/counts/W12-how-each-place-keeps-its-distance-1-40.txt): WHERE THE LINE PASSES THE
// TERRACE'S PEOPLE terracePlan TRIES EACH PLACE AGAINST THE LINE (its ok(): CROWD.CLEAR and a body's) and deals again:
// at the parapet, before the temple and in its porch, on the front walk's run east of the line, on the garden's paths
// and in the walk round the temple's room (the least 20.76 m). THE OTHER PLACES OF THE TERRACE ARE LAID WITH NO TEST
