  ARCH3: [0.4, 0.3], FACE_KEEP: 0.6, PORCH_KEEP: 1.25,
  // THE STANDERS ON THE OPEN GROUND: GATHER gatherings (times the density), each GATHER_KNOTS knots of KNOT_N people
