  GATHER: 24, GATHER_KNOTS: [3, 6], GATHER_R: [3.2, 6.5], LONE: 70, KNOT_N: [2, 5], AXIS_CLEAR: 3.8,
  // THE LITTERS SET DOWN: before each barred gap beside the gap of an axis (eight places), STAND_OUT m out from the
