  ROWS: [{ s: 7.95, k0: 2, k1: 11, face: 1 }, { s: 19.35, k0: 3, k1: 6, face: -1 }, { s: 19.35, k0: 8, k1: 11, face: -1 }],
  LANE: { S: [13.4, 15.9], T: [4, 60], WALK: 34, STAND: [0.7, 1.7], BUSY: 0.85 },
  // THE PATCH THE CROWDS KEEP OFF: the dug block's plan set before OUR front, NOT the dug place, OURS (the block is
