  DUG: { W: 13, D: 12, GAP: 7.8, FROM_NE: 81.5, KEEP: 0.5 },
  // THE TERRACE'S PEOPLE (terracePlan): AT THE PARAPET (PARAPET knots times the density, PARAPET_BACK m
  // behind it, none within ALTAR_CLEAR m of the temple's middle line: nobody at the altar), BEFORE THE TEMPLE (on the
  // paved strip and in the porch: TEMPLE knots), ON THE FRONT WALK (FRONT walkers strolling the paved
  // border behind the parapet), IN THE THREE COLUMNED WALKS (WALKS standers' knots and STROLL walkers a side), ON
