  const gapOf = (i) => { i = ((i % nB) + nB) % nB; const a = posts[i], b = posts[(i + 1) % nB], w = hyp(b[0] - a[0], b[1] - a[1]), f = frames[i];
    return { i, x: (a[0] + b[0]) / 2, z: (a[1] + b[1]) / 2, ux: (b[0] - a[0]) / w, uz: (b[1] - a[1]) / w, half: w / 2 - G.POST_KEEP, nx: f.Nx, nz: f.Nz, ax: f.ox - f.Nx * O.INTO_ARCH, az: f.oz - f.Nz * O.INTO_ARCH }; };
