  const crossesBlock = (x0, z0, x1, z1, m) => { let t0 = 0, t1 = 1; const dx = x1 - x0, dz = z1 - z0;
    if (Math.max(x0, x1) < blk[0] - m || Math.min(x0, x1) > blk[1] + m || Math.max(z0, z1) < blk[2] - m || Math.min(z0, z1) > blk[3] + m) return false;
    for (const [p, q] of [[-dx, x0 - blk[0] + m], [dx, blk[1] + m - x0], [-dz, z0 - blk[2] + m], [dz, blk[3] + m - z0]]) { if (p === 0) { if (q < 0) return false; } else { const r = q / p; if (p < 0) { if (r > t1) return false; if (r > t0) t0 = r; } else { if (r < t0) return false; if (r < t1) t1 = r; } } }
    return true; };
