// reads this part's laws as plain names, and of the arena's section only its exported plan of the prize balls' showers.)
// ====================================================================================================================
// flavian-amphitheatre, THE SEATING AND ITS PEOPLE.
//
// WHAT STANDS HERE
//   buildSeating(ctx, hero, opts) builds, on the MAIN PART'S section and plan (M, SECTION, ringA, ringB, BOWLC, RIG:
//   no measure of the building is written here a second time), every surface a person sits or stands on that the
//   hero leaves out when opts.seats is false, and the people on it. Three draw calls:
//   'steps'   THE STONE AND THE TIMBER, true steps all round (no drawn rows on a slope): the podium's five platforms
//             and their risers; the first zone's twenty marble rows and the second zone's sixteen; the wooden
//             gallery's eleven steps; the standing room's floor; the EIGHTY MOUTHS of the stairs where the make drew
//             them (even bays' middles from row 9 of the first zone, odd bays' from row 3 of the second), each a hole
//             three rows deep with a stair of four steps going down, two cheeks and a door under the row behind, dim
//             and dimmer inward; a stair 0.8 m wide through every mouth's middle, the zone's whole height (drawn on
//             the treads as half steps), which cuts each zone into forty wedges. The rows end at the two gate blocks
//             and the podium's places end at the two boxes. The surfaces follow the hero's own loft (its 192 knots).
//             Each tread also carries the shade its sitters make (a dark line along their backs) and, for a place
//             that is no card, the figure seen from above (lap, shoulders, head; the raised hands and the cloth of one
//             on his feet): the look down a row, where an upright ribbon is thin. A RISER behind a row of people
//             stands in their shade (order three: the shade on the step behind them); the stone's own tone is unchanged.
//   'ribbons' THE PEOPLE BY THE PROOF'S WAY d: one upright strip along each of the 63 lines of people (5 podium, 20,
//             16, 11, 5 standing files, 2 boxes of 3 rows), cut at the stairs, mouths, gate blocks and boxes. Its
//             shader reads one texel a place from the seats' picture (cloth, phase, flags, skin) and draws the
//             figure of that place. The triangles do not grow with the people.
//   'cards'   THE NEAR PEOPLE, BY PLACE: every taken place the flown line comes nearer than SEAT.NEAR (44 m, by the
//             head's height) is one instanced card, a figure of plain rounds (body, head, lap, shins, two hands, now
//             and then a cloth, a hat or a parasol; a plain movable seat under it on the podium and in the boxes).
//             Which places are cards is the same on every seed and every clock: it follows the LINE, never the lens.
//   NO FACE anywhere: a head is one plain round, hair over skin, or a cloth, a hat.
//   THE RINGS OF DIFFERENT PEOPLE (order three, point 1; dressOf, clothOf; the research's sections 4.1 to 4.24), from
//   the arena outward:
//     the podium         the senators in the whitest togas on movable seats, about half with the purple stripe or edge
//                        shown; beside the west gate the envoys in their own dyed dress (THE LOOK OF FOREIGN
//                        DRESS IS UNKNOWN; ours);
//     the knights' rows  the first zone's rows 1 to 14 (SEAT.KNIGHT_ROWS): white togas, and among them one in twenty in
//                        a scarlet, purple or grass green cloak (the poet's marked men sat in these rows);
//     the six rows above plain citizens in togas of undyed wool (a warmer, duller white), a few in pale tunics;
//     the second zone    its lower rows undyed togas MIXED WITH DYED TUNICS AND CLOAKS (madder red, weld yellow, woad
//                        blue, green and their kin), bench group by bench group, so that the dye lies in blocks; from
//                        its row 10 up (SEAT.DARK_FROM) the dark undyed cloaks, browns and greys;
