//   THE MOTION (MOTION, doingAt, wedgeUpAt, reachAt) runs on the world's clock (U.uTime) and the seat's place alone. NO
//   WAVE RUNS ROUND. WHOLE WEDGES ARE ON THEIR FEET (order three, point 4): every wedge between two stairs has a
