// THE WEDGES AND THE BENCH GROUPS (order three: "within a zone the wedges differ a little by chance"; the sources: places
// were given out by length of bench to GROUPS, a college with its guests and dependants; sections for public guests and
// for a far city's people are cut on this building's stone). Two tables of chance of this section's own, from two forks:
//   'amphitheatre-seating-wedges:' + seed   for each zone's forty wedges: how much dyed cloth it holds beside its
//                                           zone's share, which dye leads in it, where its bench groups begin
//   'amphitheatre-seating-groups:' + seed   for a bench group (a stretch of bench about 5 m long, four rows deep): whether
//                                           it goes in one cloth, and in which
// THE GUESTS' WEDGES (INVENTED BY NEED: where they lie. WRITTEN: that public guests and a far city's people had
// sections of their own, cut on this building's stone AT AN UNKNOWN DATE, PERHAPS LATER THAN 80; that the far peoples
// came to these games (a book of poems whose date is disputed); that envoys sat among the senators (of a theatre,
// years before)): the first zone's wedges either side of the WEST gate hold the guests and the far peoples in their
// own dyed dress, and the podium beside that gate the envoys: at the west gate by the design's word (the gate the
