// ================================================================== THE SHADERS
const f2 = (v) => v.toFixed(3), v3 = (a) => 'vec3(' + a.map(f2).join(', ') + ')';
const cMix = (C) => `vec3(0., mix(${f2(C[0][0])}, ${f2(C[1][0])}, up), mix(${f2(C[0][1])}, ${f2(C[1][1])}, up))`;
// the kinds of the stone's faces
