// THE CROWD'S MOTION, by the seat's place and the world's clock alone (never the lens, never the metres flown).
// NO WAVE RUNS ROUND. The sources' motions (the research's sections 4 to 6), as order three has them:
//  WEDGES ON THEIR FEET: every wedge between two stairs has a round of its own (MOTION.WEDGE_ROUND); once in it the WHOLE
//    wedge is on its feet for MOTION.WEDGE_UP seconds, arms up, napkins and toga folds waved; half a round later, seated,
//    it claps in time, every pair of hands on the one beat of the wedge.
//  HALVES: the bowl's two halves either side of the long axis shout by turns (a round of MOTION.HALF_ROUND seconds, the
//    answer MOTION.HALF_ANSWER seconds after the call): in the half whose turn it is a share MOTION.HALF_SHARE of its
//    wedges, drawn anew each round, rise together. So at any time about a tenth to a fifth of the wedges stand, more of
//    them in the half that shouts: at every clock some wedges stand among seated ones.
//  THE PRIZE BALLS: where a shower falls (the arena section's law: its showers' periods, clocks and wedges are handed to
//    the shaders as they stand), the people of the two marble zones within the shower's wedge rise and reach up with
//    both arms for the seconds of its fall, and sit again. They wave no cloth then: the reach is the counted one (ARM).
//  CLOTHS: in a wedge on its feet those who carry a napkin and half of the rest (MOTION.CLOTH_SHARE: a fold of the
//    toga) wave a cloth over their heads; one who carries a napkin waves it now and then alone. HERE AND THERE one stands up for a while. Everybody shifts a little; one on his feet bends
//    his knees a little in his own time (never higher than the count's figure).
