  for (let i = 0; i < deal.places; i++) { const k = (deal.lineOf[i] * TW + deal.kOf[i]) * 4, j = i * 4; cells[k] = deal.who[j]; cells[k + 1] = deal.who[j + 1]; cells[k + 2] = deal.who[j + 2]; cells[k + 3] = deal.who[j + 3]; }
  const seatsTex = new THREE.DataTexture(cells, TW, TH, THREE.RGBAFormat, THREE.UnsignedByteType);
  seatsTex.minFilter = THREE.NearestFilter; seatsTex.magFilter = THREE.NearestFilter; seatsTex.generateMipmaps = false; seatsTex.needsUpdate = true;
  // THE PRIZE BALLS' SHOWERS, as the arena section's law deals them for this seed and visit (read here, never copied):
  // each shower's period, its place on the clock and its sixteen wedges; the breadth of a wedge and the seconds of a fall
