    g.setAttribute('aCell', new THREE.BufferAttribute(G.cell.slice(0, G.n * 4), 4)); await Y();
    g.setAttribute('aPl', new THREE.BufferAttribute(G.pl.slice(0, G.n * 4), 4)); await Y();
    g.setAttribute('aIn', new THREE.BufferAttribute(G.inn.slice(0, G.n * 2), 2)); await Y();
