  const stepsMat = new THREE.ShaderMaterial({ uniforms, vertexShader: STEPS_VS, fragmentShader: STEPS_FS, side: THREE.DoubleSide });
  add('steps', new THREE.Mesh(await geoOf(G), stepsMat), G.ni / 3);
