    const ao = L.group === GROUP.GALLERY ? galAo(L.d) : L.group === GROUP.STANDING ? 0.4 : 1;
    if (L.oval) emitFace(G, L, cellsOf(L, true), [L.d, L.floorY], [L.d, L.seatY + top], { id: L.id, code, dA: L.d, dB: L.d, locA: L.floorY - L.seatY, locB: top, aoA: ao, aoB: ao, people: true, cut: true, runsOnly: true });
