//    oar's splash and the water it leaves) are never smaller than the footprint across each of their two breadths and
//    grow fainter by the product of the two covers. A MARK'S WAVES (a hull's ripple, the rings round a thing that
//    stands) go to their MEAN as the footprint across them outgrows them (between 0.22 and 0.6 of a wave's length): a
//    quarter of their full light and a quarter of their full dark, a true averaging, not nought. IT IS THE ONE FILTER:
