const INSIDE = lin('#33271c'), FLOOR = lin('#2b2118'), THWART = lin('#4b3927'), BLADE = lin('#e9e1c8'), CREW_CLOTH = [lin('#dcd3bd'), lin('#cfc4a8'), lin('#c7b999'), lin('#d6ccb6')];
const CLOTH = [lin('#d6ccb6'), lin('#c2b393'), lin('#a98f68'), lin('#8a6e4d'), lin('#b9a98c')], SKIN = lin('#a8785a'), HAIR = lin('#2a2019');
// the wading handlers' tunics: the palest undyed cloth, so that a figure stands off the water beside its animal
